<textarea className="w-full bg-surface-container-low rounded-lg p-3 text-xs text-on-surface focus:outline-none focus:bg-surface-container transition-colors resize-none leading-relaxed placeholder:text-on-surface-variant/50" id="audit-memo" maxLength={500} placeholder="Enter operational justification for clearing queue..." rows={2} defaultValue="Routine post-London close reconciliation. All latency and spread widening verified against LMAX benchmark feeds." />
